_seen = {}

def out(level, code, msg, extra=""):
    """같은 코드의 WARN이 쏟아지면 리포트를 못 읽는다. 유형당 5건까지만 찍는다."""
    if level == "WARN":
        _seen[code] = _seen.get(code, 0) + 1
        if _seen[code] == 6:
            print(f"  🟡 WARN [{code}] … 이하 생략 (같은 유형 반복)")
        if _seen[code] >= 6:
            return 0
    icon = {"FAIL": "🔴 FAIL", "WARN": "🟡 WARN", "OK": "✅ OK  "}[level]
    print(f"  {icon} [{code}] {msg}" + (f"\n          ↳ {extra}" if extra else ""))
    return 1 if level == "FAIL" else 0


def strip_code(t):
    """코드블록·인용블록 제거본 (본문 규칙은 산문에만 적용)."""
    return re.sub(r"```.*?```", "", t, flags=re.S)


def parse_front(t):
    m = re.match(r"^---\n(.*?)\n---\n", t, re.S)
    if not m:
        return {}, t
    fm = {}
    for line in m.group(1).split("\n"):
        if ":" in line and not line.startswith(" "):
            k, v = line.split(":", 1)
            fm[k.strip()] = v.strip().strip('"')
    return fm, t[m.end():]


def first_prose(body):
    """티스토리 원고의 제목(H1) 뒤, 첫 표·목록·인용·헤딩·코드 앞까지의 순수 문단(이미지 임베드는 건너뛴다).
    2026-09-18 실측: 티스토리는 메타 디스크립션 칸이 없고 본문 텍스트 첫 ~400자를
    <meta name=description>·og:description으로 내보낸다(발행 12편, 볼트 description 일치 0/12)."""
    i = 0 if body.startswith("# ") else body.find("\n# ")
    b = body[i + 1:] if i > 0 else body
    b = re.sub(r"^# .*\n", "", b, count=1)
    out = []
    for line in b.split("\n"):
        s = line.strip()
        if not s or s.startswith("![["):
            continue
        if s.startswith(("|", "- ", "* ", "> ", "#", "```")) or re.match(r"^\d+\. ", s):
            break
        s = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", s)
        out.append(s.replace("**", "").replace("`", ""))
    return " ".join(out)


def check_image_markers(body, platform, fails):
    """`[이미지 n — 설명]`은 네이버 관행(뒤에 임베드가 붙어야 정상). 티스토리는 금지."""
    for m in re.finditer(r"\[이미지 \d+\s*[—-][^\]]*\]", body):
        tail = body[m.end():m.end() + 120]
        if platform == "tistory":
            fails[0] += out("FAIL", "P1", "티스토리 원고에 이미지 자리표시자 (임베드만 남길 것)", m.group(0))
        elif not re.match(r"\s*!\[\[[^\]]+\.png\]\]", tail):
            fails[0] += out("FAIL", "P1", "이미지 자리표시자 뒤에 임베드가 없다", m.group(0))


# C2 (2026-10-09 QA-7, Thomas 승인 10-08): 실측·채점 주장에 근거가 있는가. WARN만 — 저장을 막지 않는다.
# '모델 세 개에 돌려 채점, 앞 판 65~7x점'(/5·/7·/8)처럼 시험 결과를 숫자로 말하면 프론트매터 test_record: 나 그 기록으로 가는 링크가 있어야 한다.
# '실제로 넣어 봤습니다'는 바로 뒤에 입력·출력(인용·코드·따옴표·이미지·표)을 보여 주면 근거가 본문에 있다(10-04 '직접 확인한 장면' 형식).
# '직접 넣어 보세요/보는 칸'처럼 권하는 말은 주장이 아니라 세지 않는다. 약관을 '직접 열어 확인'한 것은 실측이 아니라 출처 확인이다.
C2_SCORE = re.compile(r"(?:돌려|돌린)[^\n.]{0,20}채점|채점(?:했|하면|한 결과|결과)|모델\s*(?:세|두|네|다섯|\d)\s*(?:개|종)에[^\n.]{0,15}돌려")
C2_TEST = re.compile(r"(?:테스트|시험)(?:해|을 해)\s*(?:봤|보니|본 결과)|(?:직접|실제로)\s*(?:넣어|돌려|해|써)\s*(?:봤|보니|본 결과)|실측(?:했|한 결과|해 보니)")
C2_EVIDENCE = re.compile(r"\]\([^)]*(?:실측|채점|점수|score|test)[^)]*\)|\[\[[^\]]*(?:실측|채점|점수)[^\]]*\]\]")


def check_claims(body, fm):
    """C2 — 근거 없는 실측·채점 주장 [(종류, 문장)]. 종류마다 첫 건만."""
    if fm.get("test_record", "").strip():
        return []
    def line_at(m):
        return body[body.rfind("\n", 0, m.start()) + 1: (body.find("\n", m.end()) + 1 or len(body) + 1) - 1].strip()
    hits = []
    for m in C2_SCORE.finditer(body):
        if not C2_EVIDENCE.search(line_at(m)):
            hits.append(("채점", line_at(m)))
            break
    for m in C2_TEST.finditer(body):
        if not re.search(r"\n>\s*\S|```|[\"“][^\"”\n]{10,}[\"”]|!\[\[|\n\|", body[m.end():m.end() + 600]):
            hits.append(("실측", line_at(m)))
            break
    return hits


def shared_text_checks(name, body, fails):
    """원고·발행본 공통 텍스트 규칙."""
    prose = strip_code(body)

    for pat, label in PLACEHOLDER:
        for m in re.finditer(pat, prose):
            fails[0] += out("FAIL", "P1", f"{label} 잔존",
                            prose[max(0, m.start() - 40):m.start() + 60].replace("\n", " ").strip())

    for pat, fix in TYPOS:
        if re.search(pat, prose):
            fails[0] += out("FAIL", "P2", f"오탈자 → '{fix}'로 수정", pat)

    # 마크다운 링크·HTML 앵커 밖에 노출된 raw URL (티스토리 /1 사고)
    naked = re.sub(r"\[[^\]]*\]\(https?://[^)]+\)", "", prose)
    naked = re.sub(r'<a [^>]*>.*?</a>', "", naked, flags=re.S)
    for m in re.finditer(r"\(?링크[:：]\s*https?://|(?<![(\]=\"'])https?://\S{20,}", naked):
        fails[0] += out("WARN", "P3", "앵커 텍스트 없는 raw URL 노출",
                        naked[m.start():m.start() + 80].replace("\n", " "))

    for org, country in FOREIGN.items():
        for m in re.finditer(re.escape(org), prose):
            window = prose[max(0, m.start() - 300):m.start() + 300]
            if not COUNTRY_HINT.search(window):
                fails[0] += out("WARN", "P4", f"'{org}' 인용에 국가/한계 단서 없음 (→ {country} 조사임을 밝힐 것)")
            break

    # 통계 검사(P5·P6)는 본문만 본다 — 원고의 발행 정보 블록(H1 앞, 메타 디스크립션·이미지 대응표)은 본문의 되풀이다(10-04)
    _h = re.search(r"^# .+$", prose, re.M)
    stat = prose[_h.end():] if _h else prose
    for m in re.finditer(r"(\d{1,3}(?:\.\d+)?)\s?%", stat):
        window = stat[max(0, m.start() - 120):m.start() + 60]
        # 10-04 2차: 요율 단어 목록만으로는 표·공식 속 법정 기준(구간 '80% 초과', '× 10%')이 다 안 걸러졌다(131건 남음).
        # 스킬 인용 규칙 3('무엇 중 몇 %')이 겨냥하는 건 인용한 통계다 — 조사·연구 맥락이거나 '82%가 찬성'처럼 대상을 셀 때만 본다
        line = stat[stat.rfind("\n", 0, m.start()) + 1: (stat.find("\n", m.end()) + 1 or len(stat) + 1) - 1]   # 같은 줄(문단)만 — 앞 문단의 '조사'를 끌어오지 않게
        after = stat[m.end():m.end() + 15]
        cited = STAT_CTX.search(line) or re.match(r"\s*(?:(?:가|이|는|만)(?![가-힣])|의\s*(?:응답|사람|손님|가게|사업자|소비자|이용자))", after)
        change = re.match(r"\s*(?:가량|정도|쯤)?\s*(?:가|이|는|만큼|씩)?\s*(?:늘|줄|증가|감소|올|내려|상승|하락|높|낮)", after)   # 증감률은 모수가 아니라 기준값 문제 — P6이 본다
        rate = RATE.search(stat[max(0, m.start() - 40):m.start()]) or RATE.search(after)
        if cited and not change and not DENOM.search(window) and not rate:
            fails[0] += out("WARN", "P5", f"{m.group(0)} 의 분모(모수) 미표기",
                            window.split("\n")[-1].strip()[:80])

    # 증감 방향 단어가 있는 통계 문장은 사람이 1차 출처와 대조 (네이버 3편 사고)
    # 10-04: 인용 통계 맥락(STAT_CTX)이 같은 줄에 있을 때만 — 법정 기준('15% 이상 줄었으면 대상')·내 계산 예시·시험 결과까지 잡아
    #        티스토리 13건 중 11건이 출처 없는 문장이었다. 네이버 3편 사고(스팸 '발표' 통계)와 완싱크 '실험'은 그대로 잡힌다
    for m in re.finditer(r"[^\n]*\d[^\n]*(증가|감소|늘었|줄었|급증|급감|배 늘|배 줄)[^\n]*", stat):
        if not STAT_CTX.search(m.group(0)):
            continue
        out("WARN", "P6", "증감 방향 통계 — 1차 출처에서 '전체값/부분값'과 방향 재확인",
            m.group(0).strip()[:100])


# C1 (2026-10-09 QA-1, Thomas 승인 10-08): 계산 블록 검산. 처음 14일(~10-23)은 WARN — 걸린 건과 미검출은 analytics/QA-C1-기록.md.
# 'a × b = N원', 'N원 = a × b시간', 'N원 — (라벨) a × b × c'를 다시 계산해 0.5%(최소 1) 넘게 다르면 경고한다(정정 전 /38: 35,160 vs 46,440).
# 처리: 단위(원·시간·주·명·배·㎡ …)는 떼고 '만원'은 ×10,000, '%'는 ÷100. '= 60,000원 + 325,000원 = 385,000원'처럼 오른쪽이 이어지면 그 합과 비교.
# 앞에 연산자가 있는 조각('1억 8천만원 × 184/365', '+ 줄미싱 18 × 2,000원')은 식 전체가 아니라 건너뛴다(10-08 시험의 오탐 60·66·52·33편).
# 범위 밖: 날짜·기한 해석(92편 해지 마감), 한글 숫자(1억 8천만원), 문장으로 쓴 계산. 이것들은 사람이 본다.
C1_NUM = r"\d[\d,]*(?:\.\d+)?"
C1_TERM = C1_NUM + r"(?:\s*(?:만\s*원|원|시간|주|명|일|개월|달|회|번|배|%|분|개|건|장|평|㎡))?"
C1_OP = r"\s*[×*÷/+−-]\s*"
C1_EXPR = rf"{C1_TERM}(?:{C1_OP}{C1_TERM})+"
C1_EQ_R = re.compile(rf"(?<![\d,.])({C1_EXPR})\s*=\s*({C1_TERM})")
C1_EQ_L = re.compile(rf"(?<![\d,.])({C1_TERM})\s*(?:=|—|:)\s*(?:[^\d\n×=]{{0,12}}?)({C1_EXPR})")
C1_RHS = re.compile(rf"{C1_TERM}(?:{C1_OP}{C1_TERM})*")


def _c1_val(term):
    t = term.replace(",", "").replace(" ", "")
    m = re.match(r"(\d+(?:\.\d+)?)(.*)", t)
    v, u = float(m.group(1)), m.group(2)
    if u.startswith("만원") or u == "만":
        v *= 10000
    if u == "%":
        v /= 100
    return v


def _c1_eval(expr, need_times=True):
    if need_times and "×" not in expr and "*" not in expr:
        return None
    terms, ops = re.findall(C1_TERM, expr), re.findall(C1_OP, expr)
    vals, sym = [], []
    for i, t in enumerate(terms):
        vals.append(_c1_val(t))
        if i < len(ops):
            sym.append({"×": "*", "*": "*", "÷": "/", "/": "/", "+": "+", "−": "-", "-": "-"}[ops[i].strip()])
    # 곱셈·나눗셈 먼저, 그다음 덧셈·뺄셈 (eval 없이)
    acc, cur = [], vals[0]
    for s, x in zip(sym, vals[1:]):
        if s == "*":
            cur *= x
        elif s == "/":
            if x == 0:
                return None
            cur /= x
        else:
            acc.append(cur); acc.append(s); cur = x
    acc.append(cur)
    total = acc[0]
    for i in range(1, len(acc), 2):
        total = total + acc[i + 1] if acc[i] == "+" else total - acc[i + 1]
    return total


def check_calc(body):
    """C1 — [(식, 다시 계산한 값)]과 검산한 식 수."""
    hits, n = [], 0
    for line in strip_code(body).split("\n"):
        seen = set()
        for rx, order in ((C1_EQ_R, "r"), (C1_EQ_L, "l")):
            for m in rx.finditer(line):
                if (m.start(), m.end()) in seen:
                    continue
                seen.add((m.start(), m.end()))
                if re.search(r"[×*÷/+−-]\s*[가-힣A-Za-z ]{0,8}$", line[:m.start()]):
                    continue
                if order == "r":
                    expr = m.group(1)
                    rhs = C1_RHS.match(line, m.start(2))
                    tv = _c1_eval(rhs.group(0), need_times=False) if rhs else _c1_val(m.group(2))
                else:
                    expr, tv = m.group(2), _c1_val(m.group(1))
                    if re.match(r"\s*[×*÷/+−-]", line[m.end(1):m.end(1) + 3]):
                        continue
                v = _c1_eval(expr)
                if v is None or tv is None or tv < 10:
                    continue
                n += 1
                if abs(v - tv) > max(1, 0.005 * tv):
                    hits.append((m.group(0).strip(), v))
    return hits, n


def check_taxonomy(raw, status):
    try:
        from . import taxonomy as bt
        cs, es = bt.load_clusters(), bt.load_entities()
    except Exception as e:
        return out("WARN", "M0", f"주제 레지스트리를 읽지 못함 — 메타데이터 검사 생략 ({e})")
    meta = bt.parse(raw) or {}
    n = 0
    for lvl, code, msg in bt.validate(meta, cs, es):
        if code == "M0":
            if status == "published":
                continue
            lvl = "WARN"
        n += out(lvl, code, msg)
    return n


# 2026-10-16 Y1~Y3 (Thomas 승인): 경쟁 블로그 3곳 비교(analytics/경쟁블로그-비교-2026-10-16.md)에서 나온 독자 접점 셋.
# 우리 글은 문장 끝 93%가 '~니다', 마무리가 참고 자료 목록으로 끝나 독자에게 묻는 문장이 없었고(댓글 0~1),
# '직접 열어 확인했습니다'라고 쓰고도 그 화면은 없었다(이미지 전부 생성 도식). 세 블로그는 해요체 도입·질문 마무리·실화면 캡처 9~14장.
# 네이버에 아직 올라가지 않은 원고부터 건다 — created가 이 날짜 이상(142편~). 43편은 이미 네이버에 예약·임시저장돼 있어 소급하지 않는다(Thomas 10-16).
STYLE_FROM = "2026-10-14"
CAPTURE_META = "thomas-capture"
# blog-capture.py BLOCKED와 같은 값 — 서버가 열지 않는 도메인(매일 작업 지시문의 '브라우저 자동화 금지', 쇼핑몰)
CAPTURE_BLOCKED = ("naver.com", "naver.me", "naver.net", "tistory.com", "daum.net", "coupang.com", "coupa.ng")
CAPTURE_MARK = re.compile(r"\[이미지 \d+\s*[—-]\s*캡처[:：]?[^\]]*\]\s*\n\s*!\[\[([^\]|]+\.png)(?:\|[^\]]*)?\]\]")


def png_text(path):
    """PNG의 tEXt·iTXt 값 {키: 문자열} — 표준 라이브러리만(맥 Python 3.9도 같은 파일을 쓴다)."""
    import struct
    import zlib
    outd = {}
    try:
        data = open(path, "rb").read()
    except OSError:
        return outd
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        return outd
    i = 8
    while i + 8 <= len(data):
        n, kind = struct.unpack(">I4s", data[i:i + 8])
        chunk = data[i + 8:i + 8 + n]
        if kind == b"tEXt" and b"\x00" in chunk:
            k, v = chunk.split(b"\x00", 1)
            outd[k.decode("latin-1")] = v.decode("latin-1")
        elif kind == b"iTXt" and b"\x00" in chunk:
            k, rest = chunk.split(b"\x00", 1)
            comp, rest = rest[0], rest[2:]
            _lang, rest = rest.split(b"\x00", 1)
            _tk, txt = rest.split(b"\x00", 1)
            try:
                outd[k.decode("latin-1")] = (zlib.decompress(txt) if comp else txt).decode("utf-8")
            except (zlib.error, UnicodeDecodeError):
                pass
        if kind == b"IEND":
            break
        i += 12 + n
    return outd


def find_asset(draft_path, name):
    """원고 위로 올라가며 _assets/<name>을 찾는다 — content/naver/x.md·content/naver/제휴/x.md·시험 임시 폴더 모두."""
    d = os.path.dirname(os.path.abspath(draft_path))
    for _ in range(4):
        p = os.path.join(d, "_assets", name)
        if os.path.exists(p):
            return p
        d = os.path.dirname(d)
    return ""


def _host_blocked(url):
    h = (urllib.parse.urlsplit(url).hostname or "").lower()
    return any(h == x or h.endswith("." + x) for x in CAPTURE_BLOCKED)


def _norm_url(u):
    u = u.split("#", 1)[0].rstrip("/")
    return re.sub(r"^https?://(www\.)?", "", u)


def _sentences(text):
    text = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", text).replace("**", "")
    return [x.strip() for x in re.split(r"(?<=[.?!？])\s+", re.sub(r"\s+", " ", text)) if len(x.strip()) >= 4]


def capture_embeds(body):
    return CAPTURE_MARK.findall(body)


def check_reader_touch(path, fm, body, fails):
    """Y1 도입 해요체 · Y2 마무리 질문 · Y3 원고가 인용한 공식 화면 캡처. 네이버 새 원고만(STYLE_FROM)."""
    # Y1 — 제목(H1)·카테고리 인용블록 뒤, 첫 구분선·소제목·이미지 앞의 문단. 쇼핑커넥트 대가 표시 문단은 정해진 문구라 뺀다
    h1 = re.search(r"^# .+$", body, re.M)
    rest = body[h1.end():] if h1 else body
    paras, started = [], False
    for para in re.split(r"\n\s*\n", rest):
        t = para.strip()
        if not t:
            continue
        if not started and t.startswith(">"):
            continue                      # 카테고리·태그 인용블록
        started = True
        if t == "---" or t.startswith("## ") or t.startswith("[이미지"):
            break
        if t.startswith(("|", ">", "!", "```")) or "쇼핑 커넥트 활동의 일환" in t:
            continue
        paras.append(t)
    sents = _sentences(" ".join(paras))[:3]
    yo = [x for x in sents if re.search(r"(요|죠)[.?!？]?[\"”’)]*$", x)]
    need = min(2, len(sents))
    if not sents or len(yo) < need:
        fails[0] += out("FAIL", "Y1", f"도입 첫 3문장 중 해요체 {len(yo)}개 — 2문장 이상을 '~요/~죠'로(본문은 합니다체 그대로)",
                        " / ".join(x[:40] for x in sents) or "도입 문단 없음")
    # Y2 — 마무리(함께 보면 좋은 글·참고 자료 앞, 마지막 구분선 뒤)에 독자에게 묻는 문장 하나
    cut = [i for i in (body.find("**함께 보면 좋은 글**"), body.find("**참고 자료**")) if i > 0]
    seg = body[:min(cut)] if cut else body
    seg = seg.rstrip()
    while seg.endswith("---"):
        seg = seg[:-3].rstrip()
    last = seg.rfind("\n---\n")
    closing = seg[last + 5:] if last >= 0 else seg[-800:]
    closing = "\n".join(l for l in closing.split("\n") if not l.lstrip().startswith(("|", ">", "!", "[이미지")))
    qs = [x for x in _sentences(closing) if re.search(r"[?？][\"”’)]*$", x)]
    if not qs:
        fails[0] += out("FAIL", "Y2", "마무리에 독자에게 묻는 문장이 없다 — 이 글의 판정·숫자로 '우리 가게는 어느 쪽인가요?'처럼 한 문장(고정 인사·같은 질문 반복 금지)",
                        closing.strip()[-80:])
    # Y3 — '[이미지 n — 캡처: …]' + blog-capture.py가 만든 PNG(메타데이터), 그 페이지가 본문에 링크된 출처일 것
    links = {_norm_url(u) for u in re.findall(r"\]\((https?://[^)\s]+)\)", body)}
    good, bad = [], []
    for name in capture_embeds(body):
        p = find_asset(path, name)
        meta = {}
        try:
            meta = json.loads(png_text(p).get(CAPTURE_META, "{}")) if p else {}
        except ValueError:
            meta = {}
        url = meta.get("url", "")
        why = ("파일 없음" if not p else "blog-capture.py 기록 없음(직접 만든 그림)" if not url or not str(meta.get("tool", "")).startswith("blog-capture")
               else "막힌 도메인" if _host_blocked(url) else "본문에 그 페이지 링크 없음"
               if not ({_norm_url(url), _norm_url(meta.get("final_url", url))} & links) else "")
        (bad if why else good).append(f"{name}({why or meta.get('host', '')})")
    if good:
        out("OK", "Y3", f"공식 화면 캡처 {len(good)}장: {', '.join(good)}")
    elif fm.get("status") == "hold" and fm.get("capture_request", "").strip() and fm.get("capture_failed", "").strip():
        fails[0] += out("WARN", "Y3", "캡처 실패 기록이 있는 hold 원고 — Thomas가 capture_request 화면을 찍어 넣은 뒤 draft로", fm.get("capture_failed", "")[:120])
    else:
        fails[0] += out("FAIL", "Y3", "공식 화면 캡처 0장 — blog-capture.py로 본문이 인용한 공식 페이지를 찍어 '[이미지 n — 캡처: …]'로 넣는다"
                        " (모든 출처가 실패하면 status: hold + capture_request:, 실패는 도구가 capture_failed:에 남긴다)", "; ".join(bad))


def check_draft(path):
    print(f"\n{'=' * 72}\n📄 DRAFT  {path}\n{'=' * 72}")
    _seen.clear()
    fails = [0]
    raw = open(path, encoding="utf-8").read()
    fm, body = parse_front(raw)
    platform = fm.get("platform", "naver")

    for k in ("title", "platform", "keywords", "tags", "status"):
        if k not in fm:
            fails[0] += out("FAIL", "F1", f"프론트매터 '{k}' 누락")
    # 2026-10-02: 티스토리는 예약 발행이 자동이라 원고의 제휴 자리표시가 그대로 나간다 → 원고 단계에서 막는다(네이버는 Thomas가 발행 때 바꾼다)
    slots = re.findall(AFFILIATE_SLOT, strip_code(body))
    if slots:
        if platform == "tistory":
            fails[0] += out("FAIL", "AF1", f"티스토리 원고에 제휴 링크 자리표시 {len(slots)}개 — 링크 노트의 쿠팡 링크로 바꾸거나 판을 만들지 않는다", " / ".join(slots[:3]))
        else:
            out("WARN", "AF1", f"제휴 링크 자리표시 {len(slots)}개 — 발행 때 쇼핑커넥트 링크로 교체", " / ".join(slots[:3]))
    if fm.get("title") and not raw.split("title:", 1)[1].lstrip().startswith('"'):
        fails[0] += out("WARN", "F2", "title이 따옴표로 안 감싸짐 (콜론이 YAML을 깬다)")

    # 2026-10-03: 요금·한도·연도 수치가 판정을 가르는 글은 다음 확인 기한을 적는다(스킬 2단계). 주간 분석이 기한 지난 글을 띄운다
    # 2026-10-07: 네이버에도 건다 — 네이버 원고 92편 중 refresh 0편이었다(검사가 티스토리 블록 안에만 있었다). 네이버 검색 가이드 원칙 5 '최신성 유지'
    refresh = re.sub(r"\s*#.*$", "", fm.get("refresh", "")).strip()   # 스킬 예시처럼 뒤에 주석을 남겨도 값만 본다
    # '가격인상·가격인하 안내문'은 문구 쓰는 법이지 가격 수치 글이 아니다(10번 오탐, 10-03) — 가격 뒤에 인상·인하가 붙으면 세지 않는다
    # 2026-10-11: 제휴 글은 본문에 판매가가 있는데 제목·키워드에 가격 말이 없어 R1이 걸리지 않았다(제휴 6편 모두 refresh 없음) — 발행 전 제휴 원고도 본다.
    # 기한은 가격 클립 날짜 +30일. 발행된 제휴 글은 G1처럼 건너뛴다(발행 후 수정 최소화, 86편은 증거 체계 전 글)
    aff_price = bool(re.search(r"\S", fm.get("affiliate", ""))) and fm.get("status") != "published"
    if (aff_price or re.search(r"요금|가격(?! ?인[상하])|비용|수수료|한도|무료|유료|플랜|구독|최저임금|세율|20[23]\d", fm.get("title", "") + " " + fm.get("keywords", ""))) and not refresh:
        fails[0] += out("WARN", "R1", ("제휴 원고인데" if aff_price else "요금·한도·연도 수치 글인데")
                        + " refresh:(다음 확인 기한 YYYY-MM-DD)가 비었다 — 요금·한도·판매가 +30일(제휴는 가격 클립 날짜부터), 연 단위 수치는 다음 개정 시행일")
    elif refresh and not re.match(r"\d{4}-\d{2}-\d{2}$", refresh):
        fails[0] += out("WARN", "R1", f"refresh: '{refresh}' — YYYY-MM-DD 날짜로 적는다")

    for expr, v in check_calc(body)[0]:
        shown = f"{v:,.0f}" if abs(v - round(v)) < 0.005 else f"{v:,.2f}"
        out("WARN", "C1", f"계산이 맞지 않는다 — 다시 계산하면 {shown} (14일 WARN, 걸린 건은 analytics/QA-C1-기록.md)", expr[:100])

    # 2026-09-27: 티스토리는 저장할 때 제목의 비ASCII 기호를 HTML 이름 엔티티로 바꿔(— → &mdash;) RSS에 '&amp;mdash;'가
    # 글자 그대로 나간다(/12~/59 전부). 구분 기호는 ASCII ': '를 쓴다. 가운뎃점·따옴표·화살표도 같은 위험이다
    if platform == "tistory":
        t = fm.get("title", "")
        if "—" in t or "&mdash;" in t or "–" in t:
            # 이미 발행·예약된 글은 제목을 바꾸지 않으므로(09-27 결정: 새 글부터) WARN으로만 남긴다.
            # 10-04: 발행 59편의 대시도 ': '로 교체했다(Thomas 결정 — 구조화 데이터 headline에 &mdash;가 글자 그대로 나갔다). 이제 경고가 뜨면 새로 생긴 것이다
            fails[0] += out("FAIL" if fm.get("status") not in ("published", "scheduled") else "WARN", "F3", "티스토리 제목에 대시(—) — 티스토리가 &mdash;로 저장해 RSS에 엔티티가 그대로 나간다. ': '로 바꿀 것")
        bad = [c for c in "·“”‘’×→…" if c in t]
        if bad:
            fails[0] += out("WARN", "F4", f"티스토리 제목에 {''.join(bad)} — 엔티티로 저장될 수 있다. ASCII 기호로")
        # 2026-10-03 티스토리 벤치마크: 35자 → 45자. 늘어난 자리는 부제의 구글 제안어 롱테일 1~2개 몫이다(AI 디코드 제목 39~51자)
        if len(t) > 45:
            fails[0] += out("WARN", "F5", f"티스토리 제목 {len(t)}자 — 45자 이내(메인 키워드 앞 15자 + 부제 롱테일)")
        # 2026-10-03: H2 섹션마다 핵심 문장 1개 굵게. 벤치마크 중앙값 13~30개 vs 우리 4개 — 모바일(조회의 75%)에서 훑어 읽을 데가 없다
        _h1b = re.search(r"^# .+$", body, re.M)
        secs = [s for s in re.split(r"^## ", body[_h1b.end():] if _h1b else body, flags=re.M)[1:]
                if not re.match(r"(자주 묻는|FAQ|참고|함께 보면)", s)]
        if secs:
            bolded = sum(1 for s in secs if re.search(r"\*\*[^*\n]{6,}\*\*", s))
            if bolded * 2 < len(secs):
                fails[0] += out("WARN", "B1", f"굵게 한 핵심 문장이 있는 H2 섹션 {bolded}/{len(secs)} — 섹션마다 결론·판정·숫자 문장 1개를 **굵게**")
            # 목록은 항목(줄)마다 센다 — '1. **렌즈를 닦습니다.** …'처럼 항목 머리말 하나씩 굵게 한 번호 목록은 훑어 읽기 좋은 형식이다
            # (10-03 첫 판은 목록 전체를 한 문단으로 세어 03·08·09·19·57·58을 잘못 잡았다). 발행 정보 블록(H1 앞)은 세지 않는다
            units = []
            for p in re.split(r"\n\s*\n", body[_h1b.end():] if _h1b else body):
                if p.lstrip().startswith(("|", ">")):
                    continue
                if re.match(r"\s*(\d+\.|[-*]) ", p):
                    units += [l for l in p.split("\n") if l.strip()]
                else:
                    units.append(p)
            stuffed = [u.strip()[:40] for u in units if len(re.findall(r"\*\*[^*\n]+\*\*", u)) >= 3]
            if stuffed:
                fails[0] += out("WARN", "B2", f"한 문단에 굵게 3개 이상 {len(stuffed)}곳 — 핵심 문장 1개만", stuffed[0])

    shared_text_checks(path, body, fails)
    for kind, line in check_claims(body, fm):
        out("WARN", "C2", f"{kind} 주장에 근거 없음 — 프론트매터 test_record: 나 기록 링크, 또는 바로 뒤에 입력·결과를 싣는다", line[:100])
    check_image_markers(body, platform, fails)

    prose = strip_code(body)
    # 발행 정보 인용블록(제목 H1 앞)만 제외한다. 본문 인용블록(예문·프롬프트)은 분량에 포함
    _h1 = re.search(r"^# ", prose, re.M)
    if _h1:
        prose = re.sub(r"^>.*$", "", prose[:_h1.start()], flags=re.M) + prose[_h1.start():]
    plain = re.sub(r"^\|.*$", "", prose, flags=re.M)
    # 2026-10-06: '**참고 자료**' 목록은 인용이지 본문이 아니다(V10도 뺀다). X1이 목록을 의무로 만든 뒤 87편이 목록만으로 S1 상한을 넘었다
    # 티스토리만 — 네이버 FORM_RANGES는 목록을 포함해 맞춘 값이다(뺐더니 94편이 3,069 → 2,713자로 S1 하한 아래로 갔다, 10-06)
    if platform == "tistory":
        plain = re.sub(r"^\s*[-*]\s*\[[^\]]*\]\(https?://[^)]*\).*$", "", plain, flags=re.M)
    plain = re.sub(r"[#>*`\[\]()!—-]", "", plain)
    chars = len(re.sub(r"\s", "", plain))
    h2 = re.findall(r"^## (.+)$", body, re.M)
    tables = len(re.findall(r"^\|.*\|.*\n\|[\s:|-]+\|", body, re.M))
    embeds = len(re.findall(r"!\[\[[^\]]+\.png\]\]", body))

    form = fm.get("form", "").strip()
    fr = (FORM_RANGES if platform == "naver" else TISTORY_FORM_RANGES).get(form) if form else None
    print(f"  · 글자수 {chars} / H2 {len(h2)}개 / 표 {tables}개 / 이미지임베드 {embeds}개"
          + (f" / 유형 {form}" if fr else ""))
    if form and not fr:
        fails[0] += out("WARN", "S0", f"form '{form}' 은 6유형 이름이 아님 — {'/'.join(FORM_RANGES)}")
    if not form:
        fails[0] += out("WARN", "S0", "프론트매터 form(글 유형) 없음 — 옛 기준으로 판정함" + (" (2,800~4,200자·이미지 5장)" if platform == "naver" else " (3,500~12,000자·이미지 6장)"))
    if fr:
        (lo, hi), (h2lo, h2hi), tmin, (ilo, ihi) = fr
    else:
        lo, hi = (2800, 4200) if platform == "naver" else (3500, 12000)
        h2lo, h2hi = (5, 8) if platform == "naver" else (6, 12)
        tmin = 2
        ilo, ihi = (5 if platform == "naver" else 6), 99
    tag = f" · {form}" if fr else ""
    # 10-04: 분량·H2·표 권장 범위는 원고를 쓸 때의 기준이다. 발행·예약 글을 맞추려면 문단을 불려야 하는데 스킬이 금지한다(1-B 5)
    # — 발행·예약 글은 정보로만 보인다. 이미지 하한(S4)은 그대로 FAIL
    if fm.get("status") in ("published", "scheduled"):
        off = [x for x, ok in ((f"글자수 {chars}(권장 {lo:,}~{hi:,})", lo <= chars <= hi), (f"H2 {len(h2)}(권장 {h2lo}~{h2hi})", h2lo <= len(h2) <= h2hi),
                                (f"표 {tables}({tmin}+)", tables >= tmin)) if not ok]
        if off:
            print(f"  · 원고 단계 권장 범위 밖(발행·예약 글이라 정보로만{tag}): " + " · ".join(off))
    else:
        if not lo <= chars <= hi:
            fails[0] += out("WARN", "S1", f"본문 글자수 {chars} (권장 {lo:,}~{hi:,}{tag})")
        if not h2lo <= len(h2) <= h2hi:
            fails[0] += out("WARN", "S2", f"H2 {len(h2)}개 (권장 {h2lo}~{h2hi}{tag})")
        if tables < tmin:
            fails[0] += out("WARN", "S3", f"표 {tables}개 ({tmin}개 이상{tag})")
    if embeds < ilo:
        fails[0] += out("FAIL", "S4", f"이미지 임베드 {embeds}개 (필요 {ilo}{'~' + str(ihi) if ihi < 99 else ''}개{tag})")
    elif embeds - len(capture_embeds(body)) > ihi:   # 10-16: 공식 화면 캡처(Y3)는 유형 상한에서 뺀다 — 생성 도식 세트만 센다
        fails[0] += out("WARN", "S4", f"이미지 임베드 {embeds}개 (캡처 제외 유형 상한 {ihi}개{tag})")

    # 헤딩 계층 — 티스토리 /2 /3 에서 깨졌던 부분
    levels = [len(m.group(1)) for m in re.finditer(r"^(#{1,4}) ", body, re.M)]
    if levels and levels[0] == 1:
        levels = levels[1:]          # 맨 위 제목 H1 한 줄은 볼트 관행
    if 1 in levels:
        fails[0] += out("FAIL", "H1", "본문 중간에 H1 — 소제목은 H2/H3만")
    if levels and levels[0] != 2:
        fails[0] += out("FAIL", "H2", f"첫 헤딩이 H{levels[0]} — H2로 시작해야 한다")
    for a, b in zip(levels, levels[1:]):
        if b - a > 1:
            fails[0] += out("FAIL", "H3", f"헤딩 건너뜀 H{a} → H{b}")
            break
    if 4 in levels:
        fails[0] += out("WARN", "H4", "H4 사용 — H2/H3만 쓴다")

    # 네이버는 모바일 가독성 때문에 문단이 짧아야 하고, 티스토리 롱폼은 여유가 있다
    limit = 150 if platform == "naver" else 300
    # 10-04: 목록·표·인용은 기호를 지우기 전의 원문으로 거른다 — 지운 뒤 거르면 '참고 자료' 목록 전체가 문단 하나(692자)로 잡혔다
    for para_raw in re.split(r"\n\s*\n", prose):   # 'raw'는 위에서 원고 전체 텍스트다 — 덮어쓰면 A1 검사가 깨진다(10-04)
        if re.match(r"\s*(?:[-*|>]|\d+\. |!\[\[|#)", para_raw):
            continue
        p = re.sub(r"\s+", " ", re.sub(r"[#>*`\[\]()!—-]", "", re.sub(r"\]\((?:https?://[^)]+)\)", "]", para_raw))).strip()
        if len(p) > limit:
            fails[0] += out("WARN", "S5", f"{len(p)}자 문단 — 분할 (상한 {limit})", p[:70])

    # 2026-10-03 M1: 사진·인용·구분선·소제목·표 없이 글만 500자 넘게 이어지는 구간 — 모바일에서 '텍스트 벽'이 된다
    # (노션 '네이버 블로그 자동 작성 툴' 가이드: 300~400자마다 리듬 장치, 500자 연속이면 실패작). 네이버만 본다
    if platform == "naver":
        _h1m = re.search(r"^# .+$", body, re.M)
        run, start, walls = 0, "", []
        for line in strip_code(body[_h1m.end():] if _h1m else body).split("\n"):
            s = line.strip()
            if re.match(r"(#{1,6} |---|>|\||!\[\[|\[이미지)", s):
                if run > 500: walls.append((run, start))
                run, start = 0, ""
                continue
            # 10-06: 링크는 앵커 글자만 센다 — 발행 화면에 URL은 보이지 않는데, 참고 자료 한 줄이 늘면 URL 길이로 벽이 됐다
            n = len(re.sub(r"\s", "", re.sub(r"[*`\[\]()]", "", re.sub(r"\]\(https?://[^)]*\)", "]", s))))
            if n and not start: start = s[:40]
            run += n
        if run > 500: walls.append((run, start))
        for n, s in walls:
            fails[0] += out("WARN", "M1", f"글만 {n}자 연속 — 사진·인용·구분선·소제목 중 하나를 사이에 (300~400자마다)", s)

    kws = [k.strip() for k in fm.get("keywords", "").strip("[]").split(",") if k.strip()]
    if kws:
        n = body.count(kws[0])
        if not 3 <= n <= 8:
            fails[0] += out("WARN", "K1", f"메인 키워드 '{kws[0]}' {n}회 (권장 3~8)")
        # 2026-09-18 상위 채널 조사(analytics/상위채널-패턴분석-2026-09-18.md): 블로그탭 1~3위 제목은 검색어 정확 일치 45%
        # (21~30위 31%)·첫 어절 위치 중앙값 0. 내 글도 제목에 정확 일치가 있으면 10위 안 55%, 없으면 35%·30위 밖 58%였다
        km = re.search(r"\s*".join(map(re.escape, re.sub(r"\s+", "", kws[0]))), fm.get("title", ""), re.I)
        if not km:
            fails[0] += out("WARN", "K2", f"제목에 메인 키워드 '{kws[0]}' 정확 일치 없음 — 결론·숫자형 제목이라도 키워드 구절은 그대로 넣는다")
        elif km.start() > 6:
            fails[0] += out("WARN", "K3", f"메인 키워드가 제목 {km.start() + 1}번째 글자에서 시작 — 상위 글은 첫 어절부터 키워드다")
        if platform == "naver":
            h1 = re.search(r"^# .+$", body, re.M)
            lead = re.sub(r"\s+", "", re.sub(r"^[>|!#].*$", "", body[h1.end():] if h1 else body, flags=re.M))[:200]
            if re.sub(r"\s+", "", kws[0]).casefold() not in lead.casefold():
                fails[0] += out("WARN", "K4", f"본문 첫 200자에 메인 키워드 '{kws[0]}' 없음 (1~3위 33% vs 21~30위 21%)")
    tags = [t.strip() for t in fm.get("tags", "").strip("[]").split(",") if t.strip()]
    if platform == "tistory":
        if not 5 <= len(tags) <= 10:
            fails[0] += out("FAIL", "T1", f"태그 {len(tags)}개 (7개 내외, 10개 이하)")
        if not FIXED_TAGS <= set(tags):
            fails[0] += out("FAIL", "T2", f"시리즈 고정 태그 누락 {FIXED_TAGS - set(tags)}")
        if "alt" not in raw.lower():
            fails[0] += out("FAIL", "A1", "이미지 alt 텍스트 대응표가 발행 정보 블록에 없다")
        # 2026-09-18: alt는 이미지와 본문의 관계를 설명해야 한다(구글 SEO 스타터 가이드). 00(대표)은 본문에 안 나가므로 제외
        for fn, alt in re.findall(r"^>\s*- `([^`]+)` — (.+)$", raw, re.M):
            if re.search(r"-00\.png$", fn):
                continue
            if re.search(r"대표\s?이미지|썸네일", alt) or len(alt.strip()) < 8:
                fails[0] += out("WARN", "A2", f"alt가 내용을 설명하지 않는다 — {fn}: '{alt.strip()}'")
        # 2026-09-18: 첫 400자 = 검색 요약. 표·목록 글자가 요약에 뭉쳐 들어가던 사고(/16~/27 전부)
        fp = first_prose(body)
        if len(fp) < 400:
            fails[0] += out("FAIL", "D1", f"첫 표·목록·인용 앞 순수 문단 {len(fp)}자 — 티스토리는 본문 첫 400자를 검색 요약으로 쓴다. 400자 이상으로 시작할 것", fp[:60])
        desc = fm.get("description", "").strip()
        # YAML 따옴표 이스케이프 해제 — 첫 문장이 큰따옴표로 시작하는 글("무료 AI는…")은 "\"…\"" 로 적어야 한다 (2026-09-18)
        desc = desc.replace('\\"', '"')
        norm = lambda x: re.sub(r"\s+", "", x)
        if not desc:
            fails[0] += out("WARN", "D2", "description 없음 — 본문 첫 문단 앞부분을 그대로 복사해 둔다")
        elif not norm(fp).startswith(norm(desc)):
            fails[0] += out("FAIL", "D2", "description이 본문 첫 문장과 다르다 — 티스토리에는 description 칸이 없고 본문 첫 400자가 나간다. 첫 문단 앞부분을 그대로 복사할 것", desc[:60])
        spoken = re.sub(r"`[^`]*`", "", strip_code(raw))
        if "&mdash;" in spoken or "&ndash;" in spoken:
            fails[0] += out("FAIL", "E1", "제목·본문에 HTML 엔티티 — 문자 '—'를 그대로 쓴다")
        # 발행 후가 아니라 원고 단계에서 잡아야 고칠 수 있다 (/1~/4가 내부링크 0개로 나갔다)
        links = set(re.findall(r"\]\((https?://[^)]*tistory\.com/\d+)\)", body))
        if len(links) < 2:
            fails[0] += out("FAIL", "L2", f"본문 내부 링크 {len(links)}개 — 실제 URL로 2개 이상")
        fails[0] += check_sources(body, fm, kws_of(fm))
    else:
        # 2026-10-07: 네이버 원고도 링크가 실제로 열리는지 본다 — 네이버 스팸 사례 안내(07-06)가 '잘못된 신청 링크'를 사용자 혼동 유형으로 꼽았다.
        # 출처 개수·참고 자료 목록(X1)은 네이버 규칙이 달라(일반 글 1~3건, 제휴 글 없음) 걸지 않는다
        fails[0] += check_links(body, fm)
    if platform != "tistory" and len(tags) != 8:
        fails[0] += out("WARN", "T3", f"네이버 태그 {len(tags)}개 (8개)")
    if platform == "naver":
        # 2026-09-23: 49~51편 원고가 다른 글 링크 0개였다 — 내부 링크 검사가 티스토리에만 있었다(09-16 라이브 31편 중 26편도 0개).
        # 같은 배치의 글은 아직 주소가 없으니 FAIL이 아니라 WARN. 발행된 글에서 고른다(kw-pipeline.py check의 '내부 링크 후보')
        own = re.search(r"/(\d{9,})", fm.get("url", "") or "")
        nlinks = {x for x in re.findall(r"blog\.naver\.com/(?:thomasai/|PostView\.naver\?blogId=thomasai&(?:amp;)?logNo=)(\d{9,})", body)
                  if not own or x != own.group(1)}
        if len(nlinks) < 2:
            fails[0] += out("WARN", "L2", f"다른 글 링크 {len(nlinks)}개 — '함께 보면 좋은 글'에 발행된 글 2개 이상")
        # 2026-10-06 G1(네이버): 발행 정보 블록이 없어 프론트매터 gap: 한 줄에 적는다(md2paste가 프론트매터를 버려 발행본에 안 나간다).
        # 발행된 글은 고칠 일이 아니라 건너뛴다(68편이 경고만 쌓인다)
        if fm.get("status") != "published" and "상위 글 공백" not in fm.get("gap", ""):
            fails[0] += out("WARN", "G1", "프론트매터 gap: 줄이 없다 — 네이버 블로그 탭 상위 글 3개가 빠뜨린 것과 이 글이 채운 자리를 적는다")
        # 2026-10-07 M0~M7: 주제 메타데이터(category·lane·cluster·intent·entity) — 정본은 blog_taxonomy.py와 볼트 clusters.tsv·entities.tsv.
        # 틀린 값은 FAIL, 빠진 필드는 WARN(이전 100편은 마이그레이션이 채웠다). 발행된 글은 빠진 필드를 따지지 않는다
        fails[0] += check_taxonomy(raw, fm.get("status"))
        if fm.get("status") not in ("published", "scheduled") and fm.get("created", "")[:10] >= STYLE_FROM:
            check_reader_touch(path, fm, body, fails)

    # 본문 결론 ↔ 표 결론 대조 (배민 게시중단 모순은 여기서만 잡힌다)
    cells = set()
    for row in re.findall(r"^\|(.+)\|$", body, re.M):
        for c in row.split("|"):
            c = c.strip()
            if 2 <= len(c) <= 30 and not set(c) <= set("-: "):
                cells.add(c)
    verdicts = sorted(c for c in cells if re.search(r"삭제|재게시|가려|공개|비공개|가능|불가|대상|해당 없음", c))
    if verdicts:
        print("  · ⚠️  사람이 직접 대조할 것 — 표의 판정 셀 vs 본문 서술이 일치하는가")
        print("       " + " / ".join(verdicts[:12]))
    return fails[0]


def kws_of(fm):
    return [k.strip() for k in fm.get("keywords", "").strip("[]").split(",") if k.strip()]


# 2026-10-06: 85~87편이 공식 도움말을 직접 읽고 확인 날짜까지 적고도 외부 링크 0개로 나갔다(75편 7개 → 85·86·87편 0개, 80·81편도 0).
# 근거 링크를 재는 검사가 없었다. 구글의 도움이 되는 콘텐츠 기준은 '출처를 밝혀 신뢰를 보이는가'를 묻는다 — 원고 단계에서 잰다.
_OWN = re.compile(r"(?:thomasai\.tistory\.com|blog\.naver\.com|m\.blog\.naver\.com)")
_VAGUE_ANCHOR = re.compile(r"\[(?:여기|이곳|링크|바로가기|클릭|출처|자세히|보기)\]\(https?://")
SOURCE_MIN = 2
_META_OPENER = re.compile(r"(살펴보|알아보|정리했|정리해 ?(?:드리|두었|봤)|소개하|다뤄 ?보|다룹니다|이번 (?:섹션|절|글)에서는|아래(?:에서|는))")


def _resolves(url):
    """Generated: the runtime opens no URL. The vault's offline answer — check_links/check_sources say nothing for it."""
    return "unknown", "오프라인"


def check_links(body, fm):
    """네이버 원고의 링크 검사(X2 열리는지·X3 앵커). 쇼핑커넥트 naver.me 링크는 열지 않는다(열면 제휴 클릭으로 잡힌다)."""
    n = 0
    h1 = re.search(r"^# .+$", body, re.M)
    text = body[h1.end():] if h1 else body
    urls = sorted({u for u in re.findall(r"\]\((https?://[^)\s]+)\)", text) if not re.search(r"naver\.me/|cr\.shopping|adcr", u) and not _OWN.search(u)})   # 내 블로그 글은 없는 글도 200을 준다 — 보지 않는다
    for u in urls:
        state, detail = _resolves(u)
        if state == "dead":
            n += out("FAIL" if fm.get("status") not in ("published", "scheduled") else "WARN", "X2",
                     f"열리지 않는 링크({detail}) — 실제로 연 주소만 쓴다", u[:90])
        elif state == "unknown" and detail != "오프라인":
            out("WARN", "X2", f"링크 응답 {detail} — 브라우저로 열리는지 확인", u[:90])
    vague = _VAGUE_ANCHOR.findall(text)
    if vague:
        n += out("WARN", "X3", f"링크 앵커가 내용을 말하지 않는다 {len(vague)}곳 — 문서 제목을 앵커로")
    return n


def check_sources(body, fm, kws):
    """티스토리 원고의 근거 링크(X1~X3)와 키워드 자리(K4·K5). 발행·예약 글은 FAIL 대신 WARN — 이미 슬롯에 앉은 글을 막지 않는다."""
    n = 0
    sev = "WARN" if fm.get("status") in ("published", "scheduled") else "FAIL"
    h1 = re.search(r"^# .+$", body, re.M)
    text = body[h1.end():] if h1 else body
    ext = sorted({u for u in re.findall(r"\]\((https?://[^)\s]+)\)", text) if not _OWN.search(u)})
    if len(ext) < SOURCE_MIN:
        n += out(sev, "X1", f"외부 근거 링크 {len(ext)}개 — 확인한 사실의 공식 페이지를 {SOURCE_MIN}개 이상 링크한다(본문 첫 인용 자리 + 끝의 **참고 자료**)")
    if not re.search(r"^\*\*참고 자료\*\*\s*$", text, re.M):
        n += out(sev, "X1", "**참고 자료** 목록이 없다 — FAQ 뒤에 출처마다 '- [문서 제목](URL) — 확인한 내용 (YYYY년 M월 D일 확인)'")
    for u in ext:
        state, detail = _resolves(u)
        if state == "dead":
            n += out("FAIL", "X2", f"열리지 않는 출처 링크({detail}) — 실제로 연 주소만 쓴다", u[:90])
        elif state == "unknown" and detail != "오프라인":
            out("WARN", "X2", f"출처 링크 응답 {detail} — 브라우저로 열리는지 확인", u[:90])
    # 2026-10-06 G1·Q1: 상위 글 공백 기록(스킬 1-B 3-1)과 H2 첫 문장 즉답(2단계 구조)
    if not re.search(r"상위 글 공백", body[:h1.start()] if h1 else ""):
        n += out("WARN", "G1", "발행 정보 블록에 '상위 글 공백' 줄이 없다 — 상위 글 3개가 빠뜨린 것과 이 글이 채운 자리를 적는다")
    lazy = []
    for head, sec in re.findall(r"^## (.+)\n((?:(?!^## ).*\n?)*)", text, re.M):
        if re.match(r"(자주 묻는|FAQ|참고)", head):
            continue
        first = next((p.strip() for p in re.split(r"\n\s*\n", sec) if p.strip() and not p.strip().startswith("![[")), "")
        if not first or first.startswith(("|", "- ", "* ", "1. ", ">", "### ")):   # H2 바로 밑 H3·표·목록이면 답 문장이 없다
            lazy.append(head[:30]); continue
        s1 = re.split(r"(?<=[.!?])\s", re.sub(r"\*\*", "", first), maxsplit=1)[0]
        if _META_OPENER.search(s1):
            lazy.append(head[:30])
    if lazy:
        n += out("WARN", "Q1", f"첫 문장이 답이 아닌 H2 {len(lazy)}곳 — 안내 문장·표·목록 대신 소제목의 답으로 시작", " / ".join(lazy[:3]))
    vague = _VAGUE_ANCHOR.findall(text)
    if vague:
        n += out("WARN", "X3", f"링크 앵커가 내용을 말하지 않는다 {len(vague)}곳 — 문서 제목을 앵커로")
    if kws:
        key = re.sub(r"\s+", "", kws[0]).casefold()
        lead = re.sub(r"\s+", "", first_prose(body))[:200].casefold()
        if key not in lead:
            n += out("WARN", "K4", f"본문 첫 200자에 메인 키워드 '{kws[0]}' 없음 — 첫 400자가 검색 요약이다")
        h2s = [re.sub(r"\s+", "", h).casefold() for h in re.findall(r"^## (.+)$", text, re.M)]
        if not any(key in h for h in h2s):
            n += out("WARN", "K5", f"H2 중 메인 키워드 '{kws[0]}'를 그대로 담은 소제목이 없다 — 1개 이상")
    return n
